/* Framegami browser application. Shared pure functions are prepended at build time. */
(function () {
'use strict';
const DATA=window.IRO_DATA, CONFIG=window.IRO_CONFIG;
if(!DATA||!CONFIG) throw new Error('Framegami data is missing. Rebuild the project.');
const styles=DATA.styles,categories=DATA.categories,sources=DATA.sources;
const byId=new Map(styles.map(s=>[s.id,s])), catMap=new Map(categories.map(c=>[c.id,c]));
const known=new Set(byId.keys()), index=buildSearchIndex(styles,categories);
const STORAGE='iro-v1';
let storageWarning=false;
const sessionStore=new Map();
function readLocal(key,fallback){try{const v=localStorage.getItem(STORAGE+':'+key);return v?JSON.parse(v):(sessionStore.has(key)?sessionStore.get(key):fallback);}catch{storageWarning=true;return sessionStore.has(key)?sessionStore.get(key):fallback;}}
function writeLocal(key,value){sessionStore.set(key,value);try{localStorage.setItem(STORAGE+':'+key,JSON.stringify(value));return true;}catch{storageWarning=true;return false;}}
const importedSaved=(()=>{try{return validateImport({schema:'iro-backup/v1',favorites:readLocal('favorites',[]),custom:readLocal('custom',[])},known);}catch{return {favorites:[],custom:[]};}})();
const rootURL=new URL(CONFIG.base||'./',location.href);
const state={lang:CONFIG.lang||'zh',page:CONFIG.page||'atlas',id:CONFIG.id||'',...readQuery(location.search),favorites:new Set(importedSaved.favorites),custom:importedSaved.custom,
 compare:normalizeCompare(readLocal('compare',[]),known),view:readLocal('view','grid')==='compact'?'compact':'grid',limit:24,model:'chatgpt',promptLang:CONFIG.lang||'zh',
 workStyle:styles[0].id,workModel:'chatgpt',workLang:CONFIG.lang||'zh',workOptions:{background:'keep',palette:'style',detail:'balanced',extra:''},workText:'',workDirty:false,customEditing:null};
let localImageURL='', toastTimer, scrollMemory=0, searchTimer, importPayload=null;
const t=(zh,en)=>state.lang==='zh'?zh:en;
const e=escapeHTML;
function icon(name){const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7M21 3l-10 10M11 5H4v15h15v-7"/>',heart:'<path d="M20.8 5.7a5.5 5.5 0 0 0-8 0l-.8.8-.8-.8a5.5 5.5 0 0 0-8 7.5L12 22l8.8-8.8a5.5 5.5 0 0 0 0-7.5Z"/>',compare:'<path d="M3 4h7v16H3zM14 4h7v16h-7z"/>',grid:'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>',list:'<path d="M4 5h3v3H4zM11 6h10M4 11h3v3H4zM11 12h10M4 17h3v3H4zM11 18h10"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V3H3v13h5"/>',edit:'<path d="m4 16 12-12 4 4-12 12H4v-4ZM14 6l4 4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 6v1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',book:'<path d="M3 4h8l1 2 1-2h8v16h-8l-1 1-1-1H3zM12 6v15"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m4 12 5 5L20 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',github:'<path d="M9 20c-5 1.5-5-2.5-7-3m14 6v-3.9a3.4 3.4 0 0 0-.9-2.7c3-.3 6.2-1.5 6.2-6.9A5.4 5.4 0 0 0 19.8 6a5 5 0 0 0-.1-3.5s-1.2-.4-3.8 1.4a13.3 13.3 0 0 0-7 0C6.3 2.1 5.1 2.5 5.1 2.5A5 5 0 0 0 5 6a5.4 5.4 0 0 0-1.5 3.8c0 5.4 3.2 6.6 6.2 6.9A3.4 3.4 0 0 0 8.8 19V23"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.book}</svg>`;}
function l(obj){return obj[state.lang];}
function catName(id){const c=catMap.get(id);return c?c[state.lang]:id;}
function familyName(s){return catMap.get(s.category)?.families[s.family]?.[state.lang==='zh'?0:1]||s.family;}
function counts(id){return styles.filter(s=>s.category===id).length;}
function ex(s,model=null,lang=null){return getDisplaySample(s,model,lang);}
function asset(path){return DATA.embeddedAssets?.[path]||new URL(path,rootURL).href;}
function getPath(page=state.page,id=state.id,lang=state.lang){return lang+'/'+(page==='atlas'?'':page==='style'?'style/'+id+'/':page+'/');}
function params(){const p=new URLSearchParams();for(const key of ['q','category','family','tag','status','sort','treatment']) if(state[key] && !(['all','editorial'].includes(state[key])))p.set(key,state[key]);return p.toString();}
function viewParams(page){if(page==='atlas'||page==='favorites')return params();if(page==='compare'){const p=new URLSearchParams();if(state.compare.length)p.set('ids',state.compare.join(','));p.set('model',state.model);p.set('pl',state.promptLang);return p.toString();}return '';}
function href(page,id='',lang=state.lang){const q=viewParams(page),route=getPath(page,id,lang)+(q?'?'+q:'');if(CONFIG.preview)return '#'+route;return new URL(route,rootURL).href;}
function syncURL(replace=false){const url=href(state.page,state.id);if(CONFIG.preview)history[replace?'replaceState':'pushState']({iro:true},'',url);else if(location.protocol!=='file:')history[replace?'replaceState':'pushState']({iro:true},'',url);}
function parseRoute(){if(CONFIG.preview){if(!location.hash)return;const [route,query='']=location.hash.slice(1).split('?');const parts=route.split('/').filter(Boolean);state.lang=LANGS.includes(parts[0])?parts.shift():state.lang;state.page=parts[0]||'atlas';state.id=parts[0]==='style'?parts[1]||'':'';Object.assign(state,readQuery('?'+query));}else if(location.protocol!=='file:'){let relative=location.pathname.slice(rootURL.pathname.length);const parts=relative.split('/').filter(Boolean);state.lang=LANGS.includes(parts[0])?parts.shift():state.lang;state.page=parts[0]||'atlas';state.id=state.page==='style'?parts[1]||'':'';Object.assign(state,readQuery(location.search));}}
function restoreViewQuery(){const raw=CONFIG.preview?(location.hash.split('?')[1]||''):location.search;const q=readComparisonQuery(raw,known);if(state.page==='compare'&&q.ids!==null)state.compare=q.ids;if(q.model)state.model=q.model;if(q.lang)state.promptLang=q.lang;}
parseRoute();restoreViewQuery();
function toast(message){if(storageWarning&&/已收藏到当前浏览器|已保存到当前浏览器|当前配方已保存|Saved on this browser|Custom recipe saved in this browser|Recipe saved\./.test(message))message=t('已暂存当前会话；浏览器无法持久保存，请导出备份。','Kept for this session only. Browser persistence is unavailable; export a backup.');clearTimeout(toastTimer);const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function persist(){const writes=[writeLocal('favorites',[...state.favorites]),writeLocal('custom',state.custom),writeLocal('compare',state.compare)];const ok=writes.every(Boolean);if(!ok)toast(t('浏览器存储不可用，请导出备份。','Browser storage unavailable. Export a backup.'));return ok;}
function navigate(page='atlas',id='',opts={}){if(state.page==='atlas')scrollMemory=window.scrollY;state.page=page;state.id=id;if(opts.resetLimit)state.limit=24;syncURL();renderShell();renderPage();window.scrollTo({top:opts.restore?scrollMemory:0,behavior:'instant'});document.getElementById('main')?.focus({preventScroll:true});}
function footer(){return `<footer class="site-footer">
 <a href="${href('atlas')}" data-nav="atlas">Framegami</a>
 <a href="${href('about')}" data-nav="about">${t('图片来源与许可','Sources and licenses')} ↗</a>
</footer>`;}
function sidebarContent(){return `<a class="side-link ${state.page==='atlas'&&!state.category?'active':''}" href="${href('atlas')}" data-nav="atlas" data-clear="true">${icon('grid')}${t('全部风格','All styles')}<span class="side-count">${styles.length}</span></a><a class="side-link ${state.page==='favorites'?'active':''}" href="${href('favorites')}" data-nav="favorites">${icon('heart')}${t('我的收藏','My collection')}<span class="side-count" data-fav-count>${state.favorites.size}</span></a><a class="side-link ${state.page==='custom'?'active':''}" href="${href('custom')}" data-nav="custom">${icon('edit')}${t('自定义配方','Custom recipes')}<span class="side-count" data-custom-count>${state.custom.length}</span></a><a class="side-link ${state.page==='workbench'?'active':''}" href="${href('workbench')}" data-nav="workbench">${icon('book')}${t('提示词工作台','Prompt workbench')}</a><div class="side-divider"></div><span class="sidebar-label">${t('风格分类','Categories')}</span>${categories.map(c=>`<button class="cat-button ${state.category===c.id&&state.page==='atlas'?'active':''}" data-category="${c.id}" ${state.category===c.id?'aria-expanded="true"':'aria-expanded="false"'}><span class="cat-glyph">${c.glyph}</span>${e(c[state.lang])}<span class="side-count">${counts(c.id)}</span></button>${state.category===c.id?`<div class="family-children">${Object.entries(c.families).map(([id,labels])=>`<button class="${state.family===id?'active':''}" data-family="${id}" data-parent="${c.id}">${e(labels[state.lang==='zh'?0:1])} <span class="side-count">${styles.filter(s=>s.category===c.id&&s.family===id).length}</span></button>`).join('')}</div>`:''}`).join('')}<div class="side-divider"></div><a class="side-link" href="${href('about')}" data-nav="about">${icon('info')}${t('关于 Framegami','About Framegami')}</a>`;}
function renderShell(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';const current=state.page;document.getElementById('site-head').innerHTML=`<a class="brand" href="${href('atlas')}" data-nav="atlas" aria-label="Framegami ${t('首页','Home')}"><span class="wordmark">Framegami</span><span class="seal">图鉴</span><span class="brand-sub">IMAGE TO IMAGE<br>STYLE ATLAS</span></a><nav class="top-nav" aria-label="${t('主导航','Main navigation')}">${[['atlas','风格图鉴','Atlas'],['workbench','提示词工作台','Workbench'],['favorites','我的收藏','Collection'],['about','关于','About']].map(([page,zh,en])=>`<a href="${href(page)}" data-nav="${page}" ${current===page?'aria-current="page"':''}>${t(zh,en)}</a>`).join('')}</nav><div class="header-tools"><button class="language-button" data-action="language" aria-label="${t('切换到英文','Switch to Chinese')}">${state.lang==='zh'?'中 / EN':'EN / 中'}</button><a class="icon-button header-github" href="https://github.com/patshin/framegami" aria-label="${t('GitHub 源码','GitHub repository')}">${icon('github')}</a><button class="icon-button mobile-menu-btn" data-action="menu" aria-label="${t('打开导航','Open navigation')}">${icon('menu')}</button></div>`;
 document.getElementById('sidebar').innerHTML=sidebarContent();document.getElementById('mobile-menu').innerHTML=`<div class="dialog-head"><h2>${t('Framegami｜图生图风格图鉴','Framegami · Style Atlas')}</h2><button data-close aria-label="${t('关闭导航','Close navigation')}">${icon('close')}</button></div>${sidebarContent()}`;document.getElementById('skip-link').textContent=t('跳到内容','Skip to content');renderTray();}
const palettePairs=[['#cfc3a7','#425f61','#ba7250'],['#d5c2b1','#9d5149','#546d68'],['#d9d5c4','#546b4b','#ae8c50'],['#c4cbd0','#405a73','#ba7a56'],['#d8c2be','#986c76','#385e65'],['#d2cbbb','#746657','#be7448']];
function abstractArt(s,large=false){const p=palettePairs[(s.order-1)%palettePairs.length];return `<div class="abstract kind-${(s.order-1)%6}" style="--bg:${p[0]};--tone:${p[1]};--tone2:${p[2]}"><i></i><span class="cover-monogram" aria-hidden="true">${e(state.lang==='zh'?s.name.zh.slice(0,2):s.name.en.split(/[ -]/).slice(0,2).map(x=>x[0]).join(''))}</span></div>`;}
function cover(s,large=false,model=null,lang=null){const example=ex(s,model,lang);return example?`<img src="${asset(!large && !CONFIG.preview && example.thumbnailPath ? example.thumbnailPath : example.path)}" alt="${e(l(s.name))}" loading="lazy" decoding="async" width="800" height="800">`:abstractArt(s,large);}
function card(s){return `<article class="style-card" data-card="${s.id}"><a class="card-link" href="${href('style',s.id)}" data-nav="style" data-id="${s.id}" aria-label="${e(l(s.name))} — ${t('查看提示词','View recipe')}"><div class="card-cover">${cover(s)}</div><div class="card-meta"><h3 class="card-title">${e(l(s.name))}</h3><p class="card-en">${e(state.lang==='zh'?s.name.en:s.name.zh)}</p><div class="card-bottom"><span>${e(familyName(s))}</span><span class="status-tag">${sampleSourceLabel(ex(s),state.lang)}</span></div></div></a><div class="card-tools"><button class="favorite-btn" data-favorite="${s.id}" aria-pressed="${state.favorites.has(s.id)}" aria-label="${t('收藏','Save')} ${e(l(s.name))}">${icon('heart')}</button><button class="compare-btn" data-compare="${s.id}" aria-pressed="${state.compare.includes(s.id)}" aria-label="${t('加入比较','Compare')} ${e(l(s.name))}">${icon('compare')}</button></div></article>`;}
function filteredEntries(){return searchStyles(index,{...state,lang:state.lang,favorites:state.page==='favorites'?state.favorites:null});}
function filtersMarkup(){const tags=[['','全部','All'],['japan','日系细分','Japanese'],['china','中国绘画','Chinese'],['linework','线条与印刷','Line & print'],['tactile','手工质感','Tactile'],['illustrated','动画与插画','Illustrated'],['retro','复古媒介','Retro'],['lab','创意改造','Lab']];return `<div class="treatment-row" role="group" aria-label="${t('转换类型','Treatment type')}">${[['all','全部条目','All entries'],['restyle','保留构图','Preserve composition'],['lab','重构画面','Reinterpret composition']].map(([id,zh,en])=>`<button data-treatment="${id}" class="${state.treatment===id?'active':''}" aria-pressed="${state.treatment===id}">${t(zh,en)} <small>${id==='all'?styles.length:styles.filter(s=>(s.preservation==='reinterpret')===(id==='lab')).length}</small></button>`).join('')}</div><div class="search-row"><label class="search-box">${icon('search')}<span class="sr-only">${t('搜索风格、技法和别名','Search styles, techniques and aliases')}</span><input id="style-search" type="search" maxlength="300" value="${e(state.q)}" placeholder="${t('搜索风格或技法，如水彩、像素画','Search styles or techniques, e.g. watercolor')}" autocomplete="off"><kbd class="keyboard-hint">/</kbd></label><select id="status-filter" class="small-select" aria-label="${t('示例图筛选','Example image filter')}"><option value="all">${t('全部风格','All styles')}</option><option value="images">${t('仅有案例图','With showcase images')}</option><option value="missing-images">${t('尚无案例图','Without showcase images')}</option><option value="examples">${t('已验证提示词','Verified prompts')}</option></select><select id="sort-filter" class="small-select" aria-label="${t('排序方式','Sort order')}"><option value="editorial">${t('编辑顺序','Editorial order')}</option><option value="name">${t('按名称排序','Name')}</option><option value="category">${t('按门类排序','Category')}</option></select><div class="display-buttons" role="group" aria-label="${t('显示方式','Display mode')}"><button data-view="grid" class="${state.view==='grid'?'active':''}" aria-pressed="${state.view==='grid'}" aria-label="${t('网格视图','Grid view')}">${icon('grid')}</button><button data-view="compact" class="${state.view==='compact'?'active':''}" aria-pressed="${state.view==='compact'}" aria-label="${t('紧凑视图','Compact view')}">${icon('list')}</button></div></div><div class="filter-row">${tags.map(([tag,zh,en])=>`<button class="filter-chip ${state.tag===tag?'active':''}" data-tag="${tag}" aria-pressed="${state.tag===tag}">${t(zh,en)}</button>`).join('')}${state.category||state.family?`<button class="filter-chip clear" data-action="clear-filters">${t('清除分类','Clear category')} ×</button>`:''}</div>${state.category?`<div class="catalog-rail" aria-label="${t('细分风格家族','Style families')}"><button data-family="" data-parent="${state.category}" class="${!state.family?'active':''}">${t('全部家族','All families')}</button>${Object.entries(catMap.get(state.category)?.families||{}).map(([id,n])=>`<button data-family="${id}" data-parent="${state.category}" class="${state.family===id?'active':''}">${e(n[state.lang==='zh'?0:1])}</button>`).join('')}</div>`:''}`;}
function renderAtlas(favorites=false){const main=document.getElementById('main');main.innerHTML=`${favorites?`<section class="page-heading"><h1>${t('我的收藏','Saved styles')}</h1><p>${t('换设备时，可以导出备份并在新设备上导入。','Export a backup to move your collection to another device.')}</p><div class="action-row"><button class="button small" data-action="export">${icon('download')}${t('导出备份','Export backup')}</button><button class="button small" data-action="import">${icon('upload')}${t('导入备份','Import backup')}</button></div></section>`:`<header class="page-heading"><h1>${state.category?e(catName(state.category)):t('图生图风格图鉴','Image-to-image style atlas')}</h1></header>`}<section id="explore">${filtersMarkup()}<div class="countline"><span id="result-count" aria-live="polite"></span><button class="export-results" data-action="export-results">${icon('download')}${t('导出当前结果','Export these results')}</button></div><div class="card-grid ${state.view==='compact'?'compact':''}" id="card-grid"></div><div class="load-more" id="load-more"></div></section>${footer()}`;
 document.getElementById('status-filter').value=state.status;document.getElementById('sort-filter').value=state.sort;renderCards(favorites);}
function renderCards(fav=state.page==='favorites'){const result=searchStyles(index,{...state,lang:state.lang,favorites:fav?state.favorites:null});document.getElementById('result-count').textContent=t(`${result.length} 条结果 · 显示 ${Math.min(state.limit,result.length)} 条`,`${result.length} results · Showing ${Math.min(state.limit,result.length)}`);document.getElementById('card-grid').innerHTML=result.length?result.slice(0,state.limit).map(card).join(''):`<div class="empty-state"><h2>${(state.status==='images'||state.status==='examples')?t('没有匹配的风格','No matching styles'):fav?t('暂无收藏','No saved styles yet'):t('没有匹配的风格','No matching styles')}</h2><p>${(state.status==='images'||state.status==='examples')?t('试试其他筛选条件。','Try a different filter.'):fav?t('在风格卡上点按心形图标，即可保存在这台设备。','Tap the heart on any style card to keep it on this device.'):t('试试中文、英文或常见别名，也可以清除筛选。','Try a Chinese or English name or an alias, or clear the filters.')}</p><button class="button" data-action="reset-search">${t('浏览全部风格','Browse all styles')}${icon('arrow')}</button></div>`;
 document.getElementById('load-more').innerHTML=result.length>state.limit?`<button class="button" data-action="more">${t('加载更多','Load more')} <span class="micro-note">${Math.min(24,result.length-state.limit)} / ${result.length-state.limit}</span>${icon('arrow')}</button>`:'';}
function sourceList(s){return s.sources.map(id=>sources.find(x=>x.id===id)).filter(Boolean).map(x=>`<a href="${e(safeHTTPS(x.url))}" target="_blank" rel="noopener noreferrer">${e(x.title)} ↗</a>`).join('');}
function modelTabs(which){const current=which==='work'?state.workModel:state.model;return `<div class="model-tabs" role="group" aria-label="${t('提示词版本','Prompt version')}">${MODELS.map(m=>`<button data-model="${m}" data-target="${which}" class="${current===m?'active':''}" aria-pressed="${current===m}">${{chatgpt:'ChatGPT',gemini:'Gemini',flux:'FLUX'}[m]}</button>`).join('')}</div>`;}
function promptLangControl(id,val){return `<select id="${id}" class="small-select" aria-label="${t('提示词语言','Prompt language')}"><option value="zh" ${val==='zh'?'selected':''}>${t('中文提示词','Chinese prompt')}</option><option value="en" ${val==='en'?'selected':''}>${t('英文提示词','English prompt')}</option></select>`;}
function renderDetail(){const s=byId.get(state.id);if(!s){renderNotFound();return;}const example=ex(s,state.model,state.promptLang),isMontage=example?.kind==='montage-derived-preview',isProcedural=example?.kind==='procedural-style-study',sameSceneOnly=example?.requestKind==='standalone-same-scene-generation',canSplit=example&&!isMontage&&!sameSceneOnly&&example.originalSha256===DATA.benchmark.sha256&&DATA.benchmark.path;const main=document.getElementById('main');const prompt=composePrompt(s,state.model,state.promptLang);main.innerHTML=`<div class="breadcrumb"><a href="${href('atlas')}" data-nav="atlas" data-restore="true">${t('风格图鉴','Atlas')}</a><span>/</span><button data-category="${s.category}">${e(catName(s.category))}</button><span>/</span><span>${e(familyName(s))}</span></div><section class="detail-grid"><div class="detail-visual">${canSplit?`<div class="split-view" id="split-view"><img src="${asset(DATA.benchmark.path)}" alt="${t('统一原图','Benchmark original')}"><img class="after-image" src="${asset(example.path)}" alt="${e(l(s.name))}"></div><label class="range-control">${isProcedural?t('原图 / 程序化预览','Original / procedural study'):t('原图 / 风格示意','Original / showcase')}<input id="split-range" type="range" min="0" max="100" value="50" aria-label="${t('拖动对比原图','Compare with the original')}"></label>`:`<div class="large-cover">${cover(s,true,state.model,state.promptLang)}</div>`}<p class="visual-note">${sampleSourceLabel(example,state.lang)}</p><div class="action-row"><button class="button favorite-btn" data-favorite="${s.id}" aria-pressed="${state.favorites.has(s.id)}">${icon('heart')}<span>${t('收藏风格','Save style')}</span></button><button class="button compare-btn" data-compare="${s.id}" aria-pressed="${state.compare.includes(s.id)}">${icon('compare')}${t('加入比较台','Add to comparison')}</button></div></div><div class="detail-copy"><h1 class="detail-title">${e(l(s.name))}</h1><p class="detail-en">${e(state.lang==='zh'?s.name.en:s.name.zh)}</p><div class="detail-tags"><span class="small-tag">${e(familyName(s))}</span></div>${modelTabs('detail')}<div class="prompt-control-row">${promptLangControl('detail-lang',state.promptLang)}</div><pre class="prompt-text" id="detail-prompt">${e(prompt)}</pre><div class="action-row"><button class="button primary" data-action="copy-detail">${icon('copy')}${t('复制完整提示词','Copy full prompt')}</button><button class="button" data-edit-style="${s.id}">${icon('edit')}${t('调整配方','Customize')}</button></div><p class="micro-note">${t('在图像工具中上传照片，粘贴提示词。','Upload a photo in your image tool and paste the prompt.')}</p><div class="action-row"><a class="button small" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">${t('打开 ChatGPT','Open ChatGPT')}${icon('external')}</a><a class="button small" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">${t('打开 Gemini','Open Gemini')}${icon('external')}</a><button class="button small" data-export-style="${s.id}">${icon('download')}${t('导出配方','Export recipe')}</button></div><div class="sources-box"><h3>${t('参考资料','References')}</h3><div class="source-links">${sourceList(s)}</div></div></div></section><section class="related"><h2>${t('同类风格','Related styles')}</h2><div class="card-grid">${styles.filter(x=>x.category===s.category&&x.id!==s.id).slice(0,4).map(card).join('')}</div></section>${footer()}`;}
function renderTray(){const el=document.getElementById('compare-tray');el.hidden=!state.compare.length||state.page==='compare';if(el.hidden)return;el.innerHTML=`<span class="tray-label">${icon('compare')} ${t('比较台','Compare')} ${state.compare.length}/4</span><div class="tray-chips">${state.compare.map(id=>`<button class="tray-chip" data-compare="${id}" title="${e(l(byId.get(id).name))}" aria-label="${t('从比较台移除','Remove from comparison')} ${e(l(byId.get(id).name))}">${e(l(byId.get(id).name))} ×</button>`).join('')}</div><button class="button" data-action="open-compare" ${state.compare.length<2?'disabled':''}>${t('并排比较','Compare side by side')} →</button><button class="tray-clear" data-action="clear-compare">${t('清空','Clear')}</button>`;}
function renderCompare(){const selected=state.compare.map(id=>byId.get(id)).filter(Boolean),hasImages=selected.length>1&&selected.every(s=>ex(s,state.model,state.promptLang)),sameInput=hasImages&&selected.every(s=>{const image=ex(s,state.model,state.promptLang);return image?.kind!=='montage-derived-preview'&&image?.requestKind!=='standalone-same-scene-generation'&&image?.originalSha256===DATA.benchmark.sha256;});document.getElementById('main').innerHTML=`<section class="page-heading"><h1>${t('风格比较','Compare styles')}</h1></section>${selected.length<2?`<div class="empty-state"><h2>${t('先选两种风格','Choose at least two styles')}</h2><p>${t('最多比较四种。在风格卡上点按双栏图标即可添加。','Compare up to four styles. Tap the two-column icon on a style card.')}</p><a class="button" href="${href('atlas')}" data-nav="atlas">${t('返回图鉴','Back to atlas')}${icon('arrow')}</a></div>`:`<div class="compare-controls">${modelTabs('compare')}${promptLangControl('compare-lang',state.promptLang)}<button class="button small" data-action="clear-compare">${t('清空比较台','Clear comparison')}</button><button class="button small" data-action="share-compare">${icon('copy')}${t('复制比较链接','Copy comparison link')}</button><button class="button small" data-action="export-compare">${icon('download')}${t('导出比较配方','Export prompts')}</button>${sameInput?`<label class="range-control">${t('同步放大','Synced zoom')}<input id="compare-zoom" type="range" min="1" max="3" step="0.1" value="1"></label>`:''}</div><div class="compare-grid" style="--cols:${selected.length}">${selected.map(s=>`<article class="compare-column">${hasImages?`<div class="zoom-window"><img src="${asset(ex(s,state.model,state.promptLang).path)}" alt="${e(l(s.name))}"></div>`:`<div class="card-cover">${cover(s,false,state.model,state.promptLang)}</div>`}<h2>${e(l(s.name))}</h2><p>${e(familyName(s))} · ${sampleSourceLabel(ex(s,state.model,state.promptLang),state.lang)}</p><h3>${t('完整提示词','Full prompt')}</h3><pre class="prompt-text">${e(composePrompt(s,state.model,state.promptLang))}</pre><div class="action-row"><button class="button small" data-copy-style="${s.id}">${icon('copy')}${t('复制','Copy')}</button><button class="button small" data-compare="${s.id}">${t('移除此项','Remove')}</button></div></article>`).join('')}</div>`}${footer()}`;renderTray();}
function workKey(){return [state.customEditing?'custom-draft-'+state.customEditing:state.workStyle,state.workModel,state.workLang].join(':');}
function saveWorkDraft(){writeLocal('draft:'+workKey(),{text:state.workText,dirty:state.workDirty,options:state.workOptions});}
function loadWorkDraft(){const saved=readLocal('draft:'+workKey(),null);if(saved&&typeof saved.text==='string'&&saved.text.length<=20000){state.workText=saved.text;state.workDirty=!!saved.dirty;state.workOptions=normalizePromptOptions(saved.options);}else if(state.customEditing){state.workDirty=true;}else{state.workOptions={background:'keep',palette:'style',detail:'balanced',extra:''};state.workText=composePrompt(byId.get(state.workStyle),state.workModel,state.workLang,state.workOptions);state.workDirty=false;}}
function fieldOptions(id,label,values,current){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${values.map(([v,zh,en])=>`<option value="${v}" ${current===v?'selected':''}>${t(zh,en)}</option>`).join('')}</select></div>`;}
function renderWorkbench(){if(!state.workText&&!state.customEditing)loadWorkDraft();document.getElementById('main').innerHTML=`<section class="page-heading"><h1>${t('提示词工作台','Prompt workbench')}</h1></section><section class="workbench-grid"><div class="work-panel"><h2>${t('配方设置','Recipe settings')}</h2><div class="field style-field"><label for="work-style">${t('基础风格','Base style')}</label><select id="work-style">${categories.map(c=>`<optgroup label="${e(c[state.lang])}">${styles.filter(s=>s.category===c.id).map(x=>`<option value="${x.id}" ${x.id===state.workStyle?'selected':''}>${e(l(x.name))}</option>`).join('')}</optgroup>`).join('')}</select></div>${fieldOptions('work-background',t('背景处理','Background'),[['keep','保留完整场景','Keep whole scene'],['simplify','保持位置，减少细节','Simplify in place'],['blank','移除背景，浅色留白','Remove background']],state.workOptions.background)}${fieldOptions('work-palette',t('配色指令','Palette direction'),[['style','遵从目标风格','Target style'],['source','优先原图色彩关系','Source relationships'],['mono','自定义单色变体','Monochrome variant']],state.workOptions.palette)}${fieldOptions('work-detail',t('细节指令','Detail direction'),[['balanced','主次平衡','Balanced'],['rich','保留次级细节','More secondary detail'],['simple','减少次要纹理','Simplified']],state.workOptions.detail)}<div class="field full-width"><label for="work-extra">${t('额外要求','Additional direction')}</label><textarea id="work-extra" maxlength="8000" placeholder="${t('例如：保留原图眼镜与服装标志性结构。','For example: retain the original glasses and distinctive clothing details.')}">${e(state.workOptions.extra)}</textarea></div><div class="full-width"><button class="button small" data-action="compose-work">${t('按设置重组提示词','Compose from controls')}${icon('arrow')}</button></div><div class="side-divider full-width"></div><div class="upload-wrap"><h2>${t('参考照片','Reference photo')}</h2><label class="local-upload" for="local-image">${icon('upload')}<span>${t('选择自己的原图','Choose your original')}</span><small>JPG · PNG · WEBP · GIF / ≤ 15 MB</small></label><input type="file" id="local-image" accept="image/jpeg,image/png,image/webp,image/gif" class="sr-only">${localImageURL?`<img id="local-preview" class="local-preview" src="${e(localImageURL)}" alt="${t('仅本地显示的用户原图','Your locally displayed original')}"><button class="button small" data-action="remove-image">${t('移除图片','Remove image')}</button>`:'<div id="local-preview-slot"></div>'}<p class="upload-note">${t('照片只在本机预览。','Photos stay on this device.')}</p></div></div><div class="work-editor"><div class="prompt-control-row"><h2 style="font:600 13px var(--sans);margin:0">${state.customEditing?t('自定义配方编辑','Editing custom recipe'):t('完整提示词','Full prompt')}</h2>${promptLangControl('work-lang',state.workLang)}</div>${modelTabs('work')}<textarea id="work-text" class="editor-area" placeholder="${t('在这里写下完整的图生图提示词。','Write your complete image-to-image prompt here.')}" maxlength="20000" spellcheck="false" aria-label="${t('可编辑的完整提示词','Editable full prompt')}">${e(state.workText)}</textarea><div class="editor-meta"><span id="work-dirty">${state.workDirty?t('已编辑','Edited'):t('按设置生成','From settings')}</span><span id="work-length">${state.workText.length.toLocaleString()} ${t('字符','characters')}</span></div><div class="action-row"><button class="button primary" data-action="copy-work">${icon('copy')}${t('复制完整提示词','Copy full prompt')}</button>${state.customEditing&&state.custom.some(x=>x.id===state.customEditing)?`<button class="button" data-action="update-custom">${icon('check')}${t('保存当前配方','Save changes')}</button>`:''}<button class="button" data-action="save-custom">${icon('heart')}${t('另存自定义配方','Save custom recipe')}</button><button class="button" data-action="export-work">${icon('download')}${t('导出 Markdown','Export Markdown')}</button></div><div class="action-row"><a class="button small" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">${t('打开 ChatGPT','Open ChatGPT')}${icon('external')}</a><a class="button small" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">${t('打开 Gemini','Open Gemini')}${icon('external')}</a><button class="button small" data-action="reset-work">${t('恢复该风格默认配方','Restore default recipe')}</button></div></div></section>${footer()}`;}
function renderCustom(){document.getElementById('main').innerHTML=`<section class="page-heading"><h1>${t('自定义配方','Custom recipes')}</h1><p>${t('配方保存在当前浏览器。','Recipes are saved in this browser.')}</p><div class="action-row"><button class="button primary" data-action="new-custom">${icon('plus')}${t('新建空白配方','New blank recipe')}</button><button class="button" data-action="export">${icon('download')}${t('导出备份','Export backup')}</button><button class="button" data-action="import">${icon('upload')}${t('导入备份','Import backup')}</button></div></section><div class="custom-list">${state.custom.length?state.custom.map(x=>`<article class="custom-card"><div class="source-meta">${e(x.model.toUpperCase())} / ${e(x.lang.toUpperCase())}</div><h2>${e(x.name)}</h2><div class="custom-tags">${normalizeTags(x.tags).map(tag=>`<span>${e(tag)}</span>`).join('')}</div><p>${e(x.prompt.slice(0,240))}${x.prompt.length>240?'…':''}</p><div class="action-row"><button class="button small" data-copy-custom="${e(x.id)}">${icon('copy')}${t('复制','Copy')}</button><button class="button small" data-edit-custom="${e(x.id)}">${icon('edit')}${t('编辑','Edit')}</button><button class="button small" data-delete-custom="${e(x.id)}">${t('删除','Delete')}</button></div></article>`).join(''):`<div class="empty-state"><h2>${t('暂无自定义配方','No custom recipes yet')}</h2><p>${t('从任意风格进入工作台调整并保存，或者直接新建一份空白提示词。','Customize a style in the workbench and save it, or start with a blank prompt.')}</p></div>`}</div>${footer()}`;}
function renderAbout(){
 const samples=styles.map(s=>ex(s)).filter(Boolean);
 const kinds=['same-input-showcase','montage-derived-preview','procedural-style-study'];
 const counts=kinds.map(kind=>{
   const group=samples.filter(image=>image.kind===kind);
   return group.length?`<li>${sampleSourceLabel(group[0],state.lang)} · ${group.length}</li>`:'';
 }).join('');
 const verified=styles.filter(s=>getAcceptedExample(s)).length;
 const repo='https://github.com/patshin/framegami';
 document.getElementById('main').innerHTML=`<section class="page-heading"><h1>${t('关于 Framegami','About Framegami')}</h1></section>
 <div class="about-grid">
   <section class="about-block"><h2>${t('示例图来源','Image sources')}</h2>
     <ul>${counts}</ul>
     <p>${t('已用完整提示词验证的风格','Styles verified with the exact prompt')} · ${verified}/${styles.length}</p>
     <a href="${repo}/blob/main/evidence/image-coverage.json">${t('逐图来源记录','Image credits and records')} ↗</a>
   </section>
   <section class="about-block" id="deployment"><h2>${t('项目与许可','Project and licenses')}</h2>
     <p><a href="${repo}">GitHub ↗</a> · <a href="${repo}/blob/main/CONTRIBUTING.md">${t('贡献指南','Contributing')} ↗</a></p>
     <p><a href="${repo}/blob/main/LICENSE">${t('代码','Code')} · MIT</a></p>
     <p><a href="${repo}/blob/main/CONTENT-LICENSE.md">${t('提示词与图片许可','Prompt and image licenses')} ↗</a></p>
   </section>
 </div>
 <details class="reference-list"><summary>${t('参考资料','References')} (${sources.length})</summary>
 <ul>${sources.map(x=>`<li><a href="${e(safeHTTPS(x.url))}" target="_blank" rel="noopener noreferrer">${e(x.title)} ↗</a></li>`).join('')}</ul></details>${footer()}`;
}
function renderNotFound(){document.getElementById('main').innerHTML=`<div class="empty-state" style="margin-top:40px"><h1>${t('找不到这个页面','Page not found')}</h1><a class="button" href="${href('atlas')}" data-nav="atlas">${t('返回图鉴','Back to atlas')}</a></div>${footer()}`;}
function renderPage(){document.title=(state.page==='style'&&byId.has(state.id)?l(byId.get(state.id).name)+' — ':'')+t('Framegami｜图生图风格图鉴','Framegami · Image-to-image Style Atlas');switch(state.page){case'atlas':renderAtlas();break;case'favorites':renderAtlas(true);break;case'style':renderDetail();break;case'compare':renderCompare();break;case'workbench':renderWorkbench();break;case'custom':renderCustom();break;case'about':renderAbout();break;default:renderNotFound();}renderTray();}
function updateToggles(){document.querySelectorAll('[data-favorite]').forEach(el=>el.setAttribute('aria-pressed',state.favorites.has(el.dataset.favorite)));document.querySelectorAll('[data-compare]').forEach(el=>{if(el.matches('.compare-btn'))el.setAttribute('aria-pressed',state.compare.includes(el.dataset.compare));});document.querySelectorAll('[data-fav-count]').forEach(el=>el.textContent=state.favorites.size);document.querySelectorAll('[data-custom-count]').forEach(el=>el.textContent=state.custom.length);renderTray();}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBackup(){download('iro-backup.json',JSON.stringify({schema:'iro-backup/v1',version:VERSION,exportedAt:new Date().toISOString(),favorites:[...state.favorites],custom:state.custom},null,2));toast(t('备份已导出。','Backup exported.'));}
function showDialog(title,body,buttons=[]){const d=document.getElementById('action-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button data-close aria-label="${t('关闭','Close')}">${icon('close')}</button></div>${body}<div class="action-row">${buttons.map(b=>`<button class="button ${b.primary?'primary':''}" data-dialog-action="${b.action}">${e(b.label)}</button>`).join('')}</div>`;d.setAttribute('aria-labelledby','dialog-title');d.showModal();return d;}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast(t('已复制。','Copied.'));return;}}catch{}const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;left:-10000px';document.body.append(area);area.select();let ok=false;try{ok=document.execCommand('copy');}catch{}area.remove();if(ok)toast(t('已复制。','Copied.'));else{const d=showDialog(t('手动复制','Copy manually'),`<p class="dialog-copy">${t('浏览器限制了剪贴板。下方内容已选中，按 Ctrl/Cmd+C 复制。','The browser restricted clipboard access. Press Ctrl/Cmd+C to copy the selected text.')}</p><textarea id="manual-copy" class="dialog-textarea" readonly>${e(text)}</textarea>`);d.querySelector('textarea').select();}}
function requestCompose(reset=false){const apply=()=>{if(reset)state.workOptions={background:'keep',palette:'style',detail:'balanced',extra:''};state.workText=composePrompt(byId.get(state.workStyle),state.workModel,state.workLang,state.workOptions);state.workDirty=false;state.customEditing=null;saveWorkDraft();renderWorkbench();};if(state.workDirty){showDialog(t('替换手动编辑的内容？','Replace your manual edits?'),`<p class="dialog-copy">${t('重组会替换当前编辑区。先另存自定义配方可保留这份文字。','Recomposing replaces the editor text. Save a custom recipe first to keep these edits.')}</p>`,[{action:reset?'confirm-reset':'confirm-compose',label:t('替换当前内容','Replace text'),primary:true},{action:'cancel',label:t('保留编辑','Keep edits')}]);}else apply();}
function refreshWorkTextFromControls(){if(state.workDirty){document.getElementById('work-dirty').textContent=t('设置已更改，点击「按设置重组提示词」应用。','Settings changed. Select Compose from controls to apply.');saveWorkDraft();return;}state.workText=composePrompt(byId.get(state.workStyle),state.workModel,state.workLang,state.workOptions);const area=document.getElementById('work-text');if(area)area.value=state.workText;const length=document.getElementById('work-length');if(length)length.textContent=state.workText.length.toLocaleString()+' '+t('字符','characters');saveWorkDraft();}
function promptFor(s){return composePrompt(s,state.model,state.promptLang);}
document.addEventListener('click',ev=>{const target=ev.target instanceof Element?ev.target.closest('a,button'):null;if(!target)return;
 if(target.tagName==='A'&&(ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey||ev.button!==0))return;
 if(target.hasAttribute('data-close')){target.closest('dialog')?.close();return;}
 if(target.dataset.nav){ev.preventDefault();document.getElementById('mobile-menu').close();if(target.dataset.clear){state.category='';state.family='';state.tag='';state.q='';state.status='all';state.treatment='all';state.limit=24;}navigate(target.dataset.nav,target.dataset.id||'',{restore:target.dataset.restore==='true'});return;}
 if(target.hasAttribute('data-category')){state.category=target.dataset.category;state.family='';state.limit=24;document.getElementById('mobile-menu').close();if(state.page!=='atlas')navigate('atlas');else{syncURL(true);renderShell();renderAtlas();}document.getElementById('explore')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return;}
 if(target.hasAttribute('data-family')){state.category=target.dataset.parent;state.family=target.dataset.family;state.limit=24;document.getElementById('mobile-menu').close();if(state.page!=='atlas')navigate('atlas');else{syncURL(true);renderShell();renderAtlas();}document.getElementById('explore')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(target.dataset.favorite){const id=target.dataset.favorite;if(!known.has(id))return;if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);persist();updateToggles();if(state.page==='favorites')renderCards(true);toast(state.favorites.has(id)?t('已收藏到当前浏览器。','Saved on this browser.'):t('已从收藏移除。','Removed from collection.'));return;}
 if(target.dataset.compare){const id=target.dataset.compare;if(!known.has(id))return;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<4)state.compare.push(id);else{toast(t('最多比较四种风格，请先移除一种。','Compare up to four styles. Remove one first.'));return;}persist();updateToggles();if(state.page==='compare'){syncURL(true);renderCompare();}return;}
 if(target.hasAttribute('data-treatment')){state.treatment=target.dataset.treatment;state.limit=24;syncURL(true);renderAtlas(state.page==='favorites');return;}
 if(target.hasAttribute('data-tag')){state.tag=target.dataset.tag;state.limit=24;syncURL(true);renderAtlas(state.page==='favorites');return;}
 if(target.dataset.view){state.view=target.dataset.view;writeLocal('view',state.view);renderAtlas(state.page==='favorites');return;}
 if(target.dataset.model){if(target.dataset.target==='work'){saveWorkDraft();state.workModel=target.dataset.model;loadWorkDraft();renderWorkbench();}else{state.model=target.dataset.model;if(state.page==='compare')syncURL(true);state.page==='compare'?renderCompare():renderDetail();}return;}
 if(target.dataset.editStyle){saveWorkDraft();state.workStyle=target.dataset.editStyle;state.workModel=state.model;state.workLang=state.promptLang;state.customEditing=null;loadWorkDraft();navigate('workbench');return;}
 if(target.dataset.copyStyle){copyText(promptFor(byId.get(target.dataset.copyStyle)));return;}
 if(target.dataset.exportStyle){const s=byId.get(target.dataset.exportStyle);download('iro-'+s.id+'.json',JSON.stringify({schema:'iro-recipe/v1',id:s.id,name:s.name,model:state.model,lang:state.promptLang,prompt:promptFor(s),validation:getAcceptedExample(s,state.model,state.promptLang)?'single-example':'untested',promptVersion:s.version,tags:s.tags,sources:s.sources.map(id=>sources.find(x=>x.id===id)?.url).filter(Boolean)},null,2));return;}
 if(target.dataset.copyCustom){const x=state.custom.find(x=>x.id===target.dataset.copyCustom);if(x)copyText(x.prompt);return;}
 if(target.dataset.editCustom){const x=state.custom.find(x=>x.id===target.dataset.editCustom);if(x){state.workText=x.prompt;state.workModel=x.model;state.workLang=x.lang;state.workDirty=true;state.customEditing=x.id;loadWorkDraft();navigate('workbench');}return;}
 if(target.dataset.deleteCustom){const id=target.dataset.deleteCustom;const x=state.custom.find(x=>x.id===id);if(x)showDialog(t('删除这份自定义配方？','Delete this custom recipe?'),`<p class="dialog-copy">${e(x.name)}<br>${t('仅删除当前浏览器中的这份内容，已导出的备份不会受影响。','Only this browser copy will be removed. Exported backups are not affected.')}</p>`,[{action:'delete:'+id,label:t('确认删除','Delete'),primary:true},{action:'cancel',label:t('取消','Cancel')}]);return;}
 if(target.dataset.dialogAction){const action=target.dataset.dialogAction,d=document.getElementById('action-dialog');if(action==='cancel'){d.close();return;}if(action==='update-custom'){const pos=state.custom.findIndex(x=>x.id===state.customEditing);if(pos<0||!state.workText.trim()){toast(t('提示词不能为空。','The prompt cannot be empty.'));return;}state.custom[pos]={...state.custom[pos],prompt:state.workText,model:state.workModel,lang:state.workLang,updatedAt:new Date().toISOString()};persist();saveWorkDraft();toast(t('当前配方已保存。','Recipe saved.'));return;}
 if(action==='save-custom'){const name=d.querySelector('#custom-name').value.trim();if(!name){d.querySelector('#custom-name').focus();return;}if(!state.workText.trim()){toast(t('提示词不能为空。','The prompt cannot be empty.'));return;}if(state.custom.length>=MAX_CUSTOM){toast(t('自定义条目已达上限，请先导出备份。','Custom recipe limit reached. Export a backup first.'));return;}const id='custom-'+(globalThis.crypto?.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2,8));state.custom.push({id,name:name.slice(0,120),prompt:state.workText,model:state.workModel,lang:state.workLang,tags:normalizeTags(d.querySelector('#custom-tags')?.value||''),createdAt:new Date().toISOString()});persist();d.close();updateToggles();toast(t('自定义配方已保存到当前浏览器。','Custom recipe saved in this browser.'));return;}if(action==='confirm-compose'||action==='confirm-reset'){d.close();state.workDirty=false;requestCompose(action==='confirm-reset');return;}if(action.startsWith('delete:')){state.custom=state.custom.filter(x=>x.id!==action.slice(7));persist();d.close();renderShell();renderCustom();return;}if(action==='confirm-import'&&importPayload){try{const merged=mergeBackup({favorites:[...state.favorites],custom:state.custom},importPayload);state.favorites=new Set(merged.favorites);state.custom=merged.custom;persist();importPayload=null;d.close();renderShell();renderPage();toast(t('备份已合并。','Backup merged.'));}catch(err){toast(err.message);}return;}}
 const action=target.dataset.action;if(!action)return;
 if(action==='language'){state.lang=state.lang==='zh'?'en':'zh';syncURL();renderShell();renderPage();writeLocal('lang',state.lang);return;}
 if(action==='menu'){document.getElementById('mobile-menu').showModal();return;}
 if(action==='more'){state.limit+=24;renderCards();return;}
 if(action==='clear-filters'){state.category='';state.family='';state.limit=24;syncURL(true);renderShell();renderAtlas(state.page==='favorites');return;}
 if(action==='reset-search'){state.q='';state.category='';state.family='';state.tag='';state.status='all';state.treatment='all';state.limit=24;if(state.page==='favorites')navigate('atlas');else{syncURL(true);renderShell();renderAtlas();}return;}
 if(action==='open-compare'){navigate('compare');return;}
 if(action==='clear-compare'){state.compare=[];persist();updateToggles();if(state.page==='compare'){syncURL(true);renderCompare();}return;}
 if(action==='copy-detail'){copyText(promptFor(byId.get(state.id)));return;}
 if(action==='copy-work'){copyText(state.workText);return;}
 if(action==='compose-work'){requestCompose();return;}
 if(action==='reset-work'){requestCompose(true);return;}
 if(action==='update-custom'){const pos=state.custom.findIndex(x=>x.id===state.customEditing);if(pos<0||!state.workText.trim()){toast(t('提示词不能为空。','The prompt cannot be empty.'));return;}state.custom[pos]={...state.custom[pos],prompt:state.workText,model:state.workModel,lang:state.workLang,updatedAt:new Date().toISOString()};persist();saveWorkDraft();toast(t('当前配方已保存。','Recipe saved.'));return;}
 if(action==='save-custom'){showDialog(t('给这份配方一个名字','Name your recipe'),`<label class="dialog-copy" for="custom-name">${t('只保存在当前浏览器，可以随时导出备份。','Saved only in this browser. You can export a backup at any time.')}</label><input class="dialog-input" id="custom-name" maxlength="120" value="${e(state.customEditing?state.custom.find(x=>x.id===state.customEditing)?.name||'':l(byId.get(state.workStyle).name))}" placeholder="${t('我的配方名称','My recipe name')}"><label class="dialog-copy tag-field" for="custom-tags">${t('标签（逗号分隔，最多12个）','Tags (comma separated, up to 12)')}</label><input class="dialog-input" id="custom-tags" maxlength="480" placeholder="${t('例如：人像、柔和、我的收藏','e.g. portraits, soft, favorites')}">`,[{action:'save-custom',label:t('保存为新配方','Save as new recipe'),primary:true},{action:'cancel',label:t('取消','Cancel')}]);return;}
 if(action==='export-work'){download('iro-custom-prompt.md',`# Framegami custom prompt\n\nModel target: ${state.workModel}\nLanguage: ${state.workLang}\nStatus: user-edited / untested\n\n${state.workText}\n`,'text/markdown;charset=utf-8');return;}
 if(action==='new-custom'){state.workText='';state.workDirty=true;state.customEditing='new';state.workOptions=normalizePromptOptions();navigate('workbench');return;}
 if(action==='remove-image'){if(localImageURL)URL.revokeObjectURL(localImageURL);localImageURL='';renderWorkbench();return;}
 if(action==='export-results'){const entries=filteredEntries();if(!entries.length){toast(t('当前没有可导出的结果。','No results to export.'));return;}download('iro-selection-'+entries.length+'.md',exportPromptCollection(entries,state.model,state.promptLang),'text/markdown;charset=utf-8');toast(t(`已导出 ${entries.length} 条配方；未测试的版本仍标为待测。`,`Exported ${entries.length} recipes with their validation status.`));return;}
 if(action==='export-compare'){download('iro-comparison.md',exportPromptCollection(state.compare.map(id=>byId.get(id)),state.model,state.promptLang),'text/markdown;charset=utf-8');return;}
 if(action==='share-compare'){if(location.protocol==='file:'||CONFIG.preview){toast(t('单文件预览不生成公共链接，请使用导出比较配方。','Standalone preview has no public URL. Export the comparison instead.'));return;}copyText(href('compare'));return;}
 if(action==='export'){exportBackup();return;}
 if(action==='import'){document.getElementById('import-file').click();return;}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='style-search'){clearTimeout(searchTimer);state.q=el.value;state.limit=24;searchTimer=setTimeout(()=>{syncURL(true);renderCards();},100);}if(el.id==='work-text'){state.workText=el.value;state.workDirty=true;document.getElementById('work-length').textContent=state.workText.length.toLocaleString()+' '+t('字符','characters');document.getElementById('work-dirty').textContent=t('已编辑','Edited');saveWorkDraft();}if(el.id==='work-extra'){state.workOptions.extra=el.value;refreshWorkTextFromControls();}if(el.id==='split-range'){document.getElementById('split-view').style.setProperty('--split',el.value+'%');}if(el.id==='compare-zoom'){document.querySelectorAll('.zoom-window').forEach(x=>x.style.setProperty('--zoom',el.value));}});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='status-filter'||el.id==='sort-filter'){state[el.id==='status-filter'?'status':'sort']=el.value;state.limit=24;syncURL(true);renderCards();return;}if(el.id==='detail-lang'||el.id==='compare-lang'){state.promptLang=el.value;if(state.page==='compare')syncURL(true);state.page==='compare'?renderCompare():renderDetail();return;}if(el.id==='work-style'||el.id==='work-lang'){saveWorkDraft();if(el.id==='work-style'){state.workStyle=el.value;state.customEditing=null;}else state.workLang=el.value;loadWorkDraft();renderWorkbench();return;}if(['work-background','work-palette','work-detail'].includes(el.id)){state.workOptions[el.id.slice(5)]=el.value;refreshWorkTextFromControls();return;}if(el.id==='local-image'){const f=el.files?.[0];if(!f)return;if(f.size>15*1024*1024||!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type)){toast(t('请使用 15 MB 内的 JPG、PNG、WebP 或 GIF。','Use a JPG, PNG, WebP or GIF under 15 MB.'));el.value='';return;}const url=URL.createObjectURL(f);try{await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>img.naturalWidth*img.naturalHeight>50e6?reject(new Error('Image too large')):resolve();img.onerror=reject;img.src=url;});if(localImageURL)URL.revokeObjectURL(localImageURL);localImageURL=url;renderWorkbench();toast(t('图片仅在本设备预览。','Image preview stays on this device.'));}catch{URL.revokeObjectURL(url);toast(t('无法读取图片，或像素尺寸过大。','Unreadable image or excessive pixel dimensions.'));}return;}if(el.id==='import-file'){const f=el.files?.[0];el.value='';if(!f)return;if(f.size>MAX_IMPORT_BYTES){toast(t('备份文件不能超过 2 MB。','Backup files must be under 2 MB.'));return;}try{importPayload=validateImport(JSON.parse(await f.text()),known);showDialog(t('合并这份备份？','Merge this backup?'),`<p class="dialog-copy">${t('已有收藏和配方会保留。','Your existing styles and recipes will be kept.')}</p><div class="import-summary">${importPayload.favorites.length} ${t('个收藏','saved styles')} · ${importPayload.custom.length} ${t('份自定义配方','custom recipes')}</div>`,[{action:'confirm-import',label:t('合并并保留已有内容','Merge and keep existing content'),primary:true},{action:'cancel',label:t('取消','Cancel')}]);}catch(err){importPayload=null;toast(t('导入失败：','Import failed: ')+err.message);}return;}});
document.addEventListener('pointermove',ev=>{if(state.page!=='compare')return;const w=ev.target instanceof Element?ev.target.closest('.zoom-window'):null;if(!w)return;const r=w.getBoundingClientRect();const x=(ev.clientX-r.left)/r.width*100,y=(ev.clientY-r.top)/r.height*100;document.querySelectorAll('.zoom-window').forEach(n=>{n.style.setProperty('--zx',x+'%');n.style.setProperty('--zy',y+'%');});});
document.addEventListener('keydown',ev=>{const tag=document.activeElement?.tagName;const typing=['INPUT','TEXTAREA','SELECT'].includes(tag)||document.activeElement?.isContentEditable;if(ev.key==='/'&&!typing&&!document.querySelector('dialog[open]')){ev.preventDefault();if(!['atlas','favorites'].includes(state.page))navigate('atlas');document.getElementById('style-search')?.focus();}if(ev.key==='Escape'&&state.page==='atlas'&&!typing&&state.q){state.q='';renderAtlas();syncURL(true);}});
window.addEventListener('popstate',()=>{parseRoute();restoreViewQuery();renderShell();renderPage();window.scrollTo({top:state.page==='atlas'?scrollMemory:0,behavior:'instant'});});
window.addEventListener('pagehide',()=>{if(localImageURL)URL.revokeObjectURL(localImageURL);});
window.addEventListener('storage',ev=>{if(!ev.key?.startsWith(STORAGE+':'))return;if(ev.key.endsWith(':favorites')){const raw=readLocal('favorites',[]);state.favorites=new Set(Array.isArray(raw)?raw.filter(x=>known.has(x)):[]);updateToggles();if(state.page==='favorites')renderCards(true);}});
renderShell();renderPage();if(storageWarning)toast(t('本地存储受限，请保留导出备份。','Local storage is restricted. Keep an exported backup.'));
})();
